 * the first `--` comment would comment out everything after it. For a runnable
 * copy use SSMS Tasks > Generate Scripts.
 *
 * Run by SQL Agent job "Sync Workflow To HANA" (enabled) every 60 minutes.
 * Writes to HANA table "<company db>"."js_budget_approval_workflow" via
 * linked server HANADB112.
 */
CREATE PROCEDURE [bud].[jsSyncBudgetApprovalWorkflow]  AS  BEGIN      SET NOCOUNT ON;        DECLARE @ServerName NVARCHAR(100);      DECLARE @OilDatabase NVARCHAR(100);      DECLARE @BeverageDatabase NVARCHAR(100);      DECLARE @MartDatabase NVARCHAR(100);        SELECT @ServerName = ConfigValue FROM jsConfiguration WHERE ConfigKey = 'ServerName';      SELECT @OilDatabase = ConfigValue FROM jsConfiguration WHERE ConfigKey = 'OilDatabase';      SELECT @BeverageDatabase = ConfigValue FROM jsConfiguration WHERE ConfigKey = 'BeverageDatabase';      SELECT @MartDatabase = ConfigValue FROM jsConfiguration WHERE ConfigKey = 'MartDatabase';        BEGIN TRY          CREATE TABLE #TempWorkflowData (              ID INT IDENTITY(1,1),              budgetId INT, docEntry INT, status NVARCHAR(50), currentStageId INT,              userName NVARCHAR(200), stageId INT, stageName NVARCHAR(100), approvalId NVARCHAR(50),              createdBy NVARCHAR(100), createdOn DATETIME, company NVARCHAR(100), rejectid NVARCHAR(50),              description NVARCHAR(MAX), currentTemplateId INT, currentStagePriority INT,              nextStageId INT, nextStageName NVARCHAR(100), objType INT, lineNum INT, visOrder INT,              docId INT, currentStageApprovers NVARCHAR(MAX), nextStageUsers NVARCHAR(MAX),              UpdateDate DATETIME DEFAULT GETDATE(), BUDGET NVARCHAR(255), SUB_BUDGET NVARCHAR(255),              Flag CHAR(1) DEFAULT 'A'          );            INSERT INTO #TempWorkflowData (              budgetId, docEntry, status, currentStageId, userName,              stageId, stageName, approvalId, createdBy, createdOn,              company, rejectid, description, currentTemplateId, currentStagePriority,              nextStageId, nextStageName, objType, lineNum, visOrder,              docId, currentStageApprovers, nextStageUsers, BUDGET, SUB_BUDGET          )          SELECT DISTINCT              jde.id, jde.docEntry, jde.status, jde.currentStageId,              (ju.firstName + ' ' + ju.lastName), js.id, js.stage, js.approvalId,              js.createdBy, js.createdOn, js.company, js.rejectid,              ( SELECT STRING_AGG(CONCAT(bsw_user.firstName,' ',bsw_user.lastName,': ',bsw.description),' | ')                FROM bud.jsBudgetStatusWorkflow bsw JOIN jsUser bsw_user ON bsw.userId = bsw_user.userId                WHERE bsw.docId = jde.id AND bsw.stageId = jde.currentStageId ),              jst.templateId, jst.priority, next_stage.id, next_stage.stage,              jded.objType, jded.lineNum, jded.visOrder, jded.docId,              ( SELECT STRING_AGG(CONCAT(next_u.firstName,' ',next_u.lastName),', ')                FROM dbo.jsUserStage next_us INNER JOIN jsUser next_u ON next_u.userId = next_us.userId                LEFT JOIN bud.jsBudgetStatusWorkflow next_bsw ON next_bsw.userId = next_us.userId                     AND next_bsw.stageId = jde.currentStageId AND next_bsw.docId = jde.id                WHERE next_us.stageId = jde.currentStageId AND next_bsw.docId IS NULL ),              ( SELECT STRING_AGG(CONCAT(next_stage_u.firstName,' ',next_stage_u.lastName),', ')                FROM jsStageTemplate next_jst JOIN jsStage next_js ON next_jst.stageId = next_js.id                JOIN jsUserStage next_stage_us ON next_js.id = next_stage_us.stageId                JOIN jsUser next_stage_u ON next_stage_us.userId = next_stage_u.userId                WHERE next_jst.templateId = jst.templateId AND next_jst.priority = jst.priority + 1 ),              b.BUDGET, b.SUB_BUDGET          FROM bud.jsDocEntry jde          JOIN jsUserStage jus ON jde.currentStageId = jus.stageId          JOIN jsUser ju ON jus.userId = ju.userId          JOIN jsStage js ON jde.currentStageId = js.id          JOIN jsStageTemplate jst ON js.id = jst.stageId          JOIN bud.jsDocEnrtyDetail jded ON jde.id = jded.docId          JOIN BUD.jsBudgetTable b ON jde.docEntry = b.DocEntry and jded.lineNum = b.LineNum          LEFT JOIN jsStageTemplate next_template ON jst.templateId = next_template.templateId                                   AND next_template.priority = jst.priority + 1          LEFT JOIN jsStage next_stage ON next_template.stageId = next_stage.id            -- tracking table          IF NOT EXISTS (SELECT * FROM sys.tables WHERE name='jsWorkflowSyncStatus' AND schema_id=SCHEMA_ID('bud'))          BEGIN              CREATE TABLE bud.jsWorkflowSyncStatus (                  ID INT PRIMARY KEY, budgetId INT, docEntry INT, objType INT, lineNum INT,                  visOrder INT, docId INT, LastSyncDate DATETIME, IsModified BIT DEFAULT 0 );          END            -- clear tracking table so temp IDs (restart at 1) don't clash with PK          TRUNCATE TABLE bud.jsWorkflowSyncStatus;            INSERT INTO bud.jsWorkflowSyncStatus (ID, budgetId, docEntry, objType, lineNum, visOrder, docId, LastSyncDate, IsModified)          SELECT T.ID, T.budgetId, T.docEntry, T.objType, T.lineNum, T.visOrder, T.docId, GETDATE(), 1          FROM #TempWorkflowData T;            DECLARE @ID INT,@budgetId INT,@docEntry INT,@status NVARCHAR(50),@currentStageId INT,              @userName NVARCHAR(200),@stageId INT,@stageName NVARCHAR(100),@approvalId NVARCHAR(50),              @createdBy NVARCHAR(100),@createdOn DATETIME,@company NVARCHAR(100),@rejectid NVARCHAR(50),              @description NVARCHAR(MAX),@currentTemplateId INT,@currentStagePriority INT,@nextStageId INT,              @nextStageName NVARCHAR(100),@objType INT,@lineNum INT,@visOrder INT,@docId INT,              @currentStageApprovers NVARCHAR(MAX),@nextStageUsers NVARCHAR(MAX),@BUDGET NVARCHAR(255),              @SUB_BUDGET NVARCHAR(255),@UpdateDate DATETIME,@Flag CHAR(1);          DECLARE @DatabaseName NVARCHAR(100),@SQLQuery NVARCHAR(MAX),@CheckQuery NVARCHAR(MAX),              @RecordExists INT,@Branch NVARCHAR(50);            DECLARE workflow_cursor CURSOR FOR          SELECT T.ID,T.budgetId,T.docEntry,T.status,T.currentStageId,T.userName,T.stageId,T.stageName,              T.approvalId,T.createdBy,T.createdOn,T.company,T.rejectid,T.description,T.currentTemplateId,              T.currentStagePriority,T.nextStageId,T.nextStageName,T.objType,T.lineNum,T.visOrder,              T.docId,T.currentStageApprovers,T.nextStageUsers,T.UpdateDate,T.BUDGET,T.SUB_BUDGET,T.Flag          FROM #TempWorkflowData T JOIN bud.jsWorkflowSyncStatus S ON T.ID = S.ID WHERE S.IsModified = 1;            OPEN workflow_cursor;          FETCH NEXT FROM workflow_cursor INTO @ID,@budgetId,@docEntry,@status,@currentStageId,@userName,              @stageId,@stageName,@approvalId,@createdBy,@createdOn,@company,@rejectid,@description,              @currentTemplateId,@currentStagePriority,@nextStageId,@nextStageName,@objType,@lineNum,              @visOrder,@docId,@currentStageApprovers,@nextStageUsers,@UpdateDate,@BUDGET,@SUB_BUDGET,@Flag;            WHILE @@FETCH_STATUS = 0          BEGIN              SELECT @Branch = Branch FROM bud.jsBudgetTable              WHERE DocEntry=@docEntry AND ObjType=@objType AND LineNum=@lineNum AND VisOrder=@visOrder;                SET @DatabaseName = CASE                  WHEN @Branch = 'OIL' THEN @OilDatabase                  WHEN @Branch = 'BEVERAGE' THEN @BeverageDatabase                  WHEN @Branch = 'MART' THEN @MartDatabase                  ELSE NULL END;                IF @DatabaseName IS NOT NULL              BEGIN                  SET @CheckQuery = 'SELECT COUNT(*) FROM "'+@DatabaseName+'"."js_budget_approval_workflow" '+                      'WHERE "budgetId"='+CAST(@budgetId AS NVARCHAR)+' AND "docEntry"='+CAST(@docEntry AS NVARCHAR)+                      ' AND "objType"='+CAST(@objType AS NVARCHAR)+' AND "lineNum"='+CAST(@lineNum AS NVARCHAR)+                      ' AND "visOrder"='+CAST(@visOrder AS NVARCHAR)+' AND "docId"='+CAST(@docId AS NVARCHAR);                    DECLARE @ResultTable TABLE (RecordExists INT);                  INSERT INTO @ResultTable EXEC (@CheckQuery) AT HANADB112;                  SELECT @RecordExists = RecordExists FROM @ResultTable;                  DELETE FROM @ResultTable;                    IF @RecordExists = 0                  BEGIN                      SET @SQLQuery = 'INSERT INTO "'+@DatabaseName+'"."js_budget_approval_workflow" '+                      '("budgetId","docEntry","status","currentStageId","userName","stageId","stageName",'+                      '"approvalId","createdBy","createdOn","company","rejectid","description","currentTemplateId",'+                      '"currentStagePriority","nextStageId","nextStageName","objType","lineNum","visOrder","docId",'+                      '"currentStageApprovers","nextStageUsers","BUDGET","SUB_BUDGET","updateDate") VALUES ('+                      CAST(ISNULL(@budgetId,0) AS NVARCHAR)+', '+CAST(ISNULL(@docEntry,0) AS NVARCHAR)+', '+                      ''''+ISNULL(@status,'')+''', '+CAST(ISNULL(@currentStageId,0) AS NVARCHAR)+', '+                      ''''+ISNULL(@userName,'')+''', '+CAST(ISNULL(@stageId,0) AS NVARCHAR)+', '+                      ''''+ISNULL(@stageName,'')+''', '+''''+ISNULL(@approvalId,'')+''', '+                      ''''+ISNULL(@createdBy,'')+''', '+''''+CONVERT(NVARCHAR,@createdOn,120)+''', '+                      ''''+ISNULL(@company,'')+''', '+''''+ISNULL(@rejectid,'')+''', '+                      ''''+REPLACE(ISNULL(@description,''),'''','''''')+''', '+CAST(ISNULL(@currentTemplateId,0) AS NVARCHAR)+', '+                      CAST(ISNULL(@currentStagePriority,0) AS NVARCHAR)+', '+CAST(ISNULL(@nextStageId,0) AS NVARCHAR)+', '+                      ''''+ISNULL(@nextStageName,'')+''', '+CAST(ISNULL(@objType,0) AS NVARCHAR)+', '+                      CAST(ISNULL(@lineNum,0) AS NVARCHAR)+', '+CAST(ISNULL(@visOrder,0) AS NVARCHAR)+', '+                      CAST(ISNULL(@docId,0) AS NVARCHAR)+', '+''''+REPLACE(ISNULL(@currentStageApprovers,''),'''','''''')+''', '+                      ''''+REPLACE(ISNULL(@nextStageUsers,''),'''','''''')+''', '+''''+REPLACE(ISNULL(@BUDGET,''),'''','''''')+''', '+                      ''''+REPLACE(ISNULL(@SUB_BUDGET,''),'''','''''')+''', '+''''+CONVERT(NVARCHAR,@UpdateDate,120)+''')';                      EXEC (@SQLQuery) AT HANADB112;                  END                  ELSE                  BEGIN                      SET @SQLQuery = 'UPDATE "'+@DatabaseName+'"."js_budget_approval_workflow" SET '+                      '"status"='''+ISNULL(@status,'')+''', "currentStageId"='+CAST(ISNULL(@currentStageId,0) AS NVARCHAR)+', '+                      '"userName"='''+ISNULL(@userName,'')+''', "stageId"='+CAST(ISNULL(@stageId,0) AS NVARCHAR)+', '+                      '"stageName"='''+ISNULL(@stageName,'')+''', "approvalId"='''+ISNULL(@approvalId,'')+''', '+                      '"createdBy"='''+ISNULL(@createdBy,'')+''', "createdOn"='''+CONVERT(NVARCHAR,@createdOn,120)+''', '+                      '"company"='''+ISNULL(@company,'')+''', "rejectid"='''+ISNULL(@rejectid,'')+''', '+                      '"description"='''+REPLACE(ISNULL(@description,''),'''','''''')+''', '+                      '"currentTemplateId"='+CAST(ISNULL(@currentTemplateId,0) AS NVARCHAR)+', '+                      '"currentStagePriority"='+CAST(ISNULL(@currentStagePriority,0) AS NVARCHAR)+', '+                      '"nextStageId"='+CAST(ISNULL(@nextStageId,0) AS NVARCHAR)+', '+                      '"nextStageName"='''+ISNULL(@nextStageName,'')+''', '+                      '"currentStageApprovers"='''+REPLACE(ISNULL(@currentStageApprovers,''),'''','''''')+''', '+                      '"nextStageUsers"='''+REPLACE(ISNULL(@nextStageUsers,''),'''','''''')+''', '+                      '"BUDGET"='''+REPLACE(ISNULL(@BUDGET,''),'''','''''')+''', '+                      '"SUB_BUDGET"='''+REPLACE(ISNULL(@SUB_BUDGET,''),'''','''''')+''', '+                      '"updateDate"='''+CONVERT(NVARCHAR,@UpdateDate,120)+''' '+                      'WHERE "budgetId"='+CAST(@budgetId AS NVARCHAR)+' AND "docEntry"='+CAST(@docEntry AS NVARCHAR)+                      ' AND "objType"='+CAST(@objType AS NVARCHAR)+' AND "lineNum"='+CAST(@lineNum AS NVARCHAR)+                      ' AND "visOrder"='+CAST(@visOrder AS NVARCHAR)+' AND "docId"='+CAST(@docId AS NVARCHAR);                      EXEC (@SQLQuery) AT HANADB112;                  END                    UPDATE bud.jsWorkflowSyncStatus SET IsModified = 0 WHERE ID = @ID;              END                FETCH NEXT FROM workflow_cursor INTO @ID,@budgetId,@docEntry,@status,@currentStageId,@userName,                  @stageId,@stageName,@approvalId,@createdBy,@createdOn,@company,@rejectid,@description,                  @currentTemplateId,@currentStagePriority,@nextStageId,@nextStageName,@objType,@lineNum,                  @visOrder,@docId,@currentStageApprovers,@nextStageUsers,@UpdateDate,@BUDGET,@SUB_BUDGET,@Flag;          END            CLOSE workflow_cursor;          DEALLOCATE workflow_cursor;          DROP TABLE #TempWorkflowData;      END TRY      BEGIN CATCH          IF CURSOR_STATUS('global','workflow_cursor') >= 0          BEGIN CLOSE workflow_cursor; DEALLOCATE workflow_cursor; END          IF OBJECT_ID('tempdb..#TempWorkflowData') IS NOT NULL DROP TABLE #TempWorkflowData;          THROW;      END CATCH  END
